// SETTINGS arrives as one item per row (key | value | type | description).
// Turn it into ONE item, e.g. { DEMO_MODE: 'TRUE', MAX_SENDS_PER_RUN: '3', ... },
// so every later node can read settings with $('Lane 4 · Settings to object').first().json.KEY
const settings = {};
for (const item of $input.all()) {
  const key = String(item.json.key ?? '').trim();
  if (!key) continue;
  const value = item.json.value;
  settings[key] = typeof value === 'string' ? value.trim() : (value ?? '');
}

// Stop early with a clear message if the sheet is missing something this lane needs.
const required = ["DEMO_MODE","DEMO_MINUTES_PER_DAY","LAUNCH_DATE","LAUNCH_TIME","EARLY_ACCESS_DAYS","WAITLIST_FORM_URL","SENDER_NAME","SENDER_EMAIL","ALLOWED_DEMO_INBOXES","MAX_SENDS_PER_RUN","SEND_DELAY_SECONDS","MIN_EMAIL_GAP_DAYS","UNSUBSCRIBE_LINE"];
const missing = required.filter((key) => settings[key] === undefined || settings[key] === '');
if (missing.length) {
  throw new Error(`The SETTINGS tab is missing a value for: ${missing.join(', ')}`);
}

// Derived values (SPEC section 5.3). Sheet booleans may come back as true or "TRUE".
settings.IS_DEMO = String(settings.DEMO_MODE).trim().toUpperCase() === 'TRUE';
const demoMinutes = Number(settings.DEMO_MINUTES_PER_DAY);
if (settings.IS_DEMO && !(demoMinutes > 0)) {
  throw new Error('DEMO_MINUTES_PER_DAY must be a number above 0 when DEMO_MODE is TRUE');
}
settings.DAY_MS = settings.IS_DEMO ? demoMinutes * 60 * 1000 : 24 * 60 * 60 * 1000;

return [{ json: settings }];

// Works out which leads are due for their next WAITLIST_NURTURE email and prepares everything the loop needs
// (rendered subject + HTML, recipient, what to write back). One output item per lead; nothing due = no items = quiet end.
const S = $('Lane 4 · Settings to object').first().json;
// ---- time helpers (SPEC 5.2 / 5.3)
const TZ = 'Asia/Kolkata';
const STAMP = "yyyy-MM-dd'T'HH:mm:ssZZ";
const nowTs = () => $now.setZone(TZ).toFormat(STAMP);
function parseTs(value) {
  if (value === undefined || value === null || String(value).trim() === '') return null;
  const text = String(value).trim();
  const tries = [
    () => DateTime.fromISO(text, { zone: TZ }),
    () => DateTime.fromFormat(text, 'yyyy-MM-dd HH:mm:ss', { zone: TZ }),
    () => DateTime.fromFormat(text, 'yyyy-MM-dd HH:mm', { zone: TZ }),
    () => DateTime.fromFormat(text, 'dd/MM/yyyy HH:mm:ss', { zone: TZ }),
    () => DateTime.fromFormat(text, 'dd/MM/yyyy', { zone: TZ }),
  ];
  for (const attempt of tries) { const d = attempt(); if (d.isValid) return d.setZone(TZ); }
  return null;
}
const parseDate = (value) => parseTs(value)?.startOf('day') ?? null;
const addDays = (dateTime, days) => dateTime.plus({ milliseconds: Number(days) * S.DAY_MS });
function launchAt(S) {
  if (S.IS_DEMO) return parseTs(S.DEMO_LAUNCH_AT);
  const [hour, minute] = String(S.LAUNCH_TIME).split(':').map(Number);
  return parseDate(S.LAUNCH_DATE)?.set({ hour, minute }) ?? null;
}
const gapOk = (row, now) => !parseTs(row.last_contacted_at) || now.toMillis() - parseTs(row.last_contacted_at).toMillis() >= Number(S.MIN_EMAIL_GAP_DAYS) * S.DAY_MS;
const isTrue = (value) => String(value ?? '').trim().toUpperCase() === 'TRUE';
// Rows read from a sheet; an empty tab comes back as one empty item (and blank rows only have a row_number), so drop those.
const rowsOf = (nodeName) => $(nodeName).all().map((item) => item.json).filter((row) => row && Object.entries(row).some(([key, v]) => key !== 'row_number' && String(v ?? '').trim() !== ''));
// ---- template renderer (SPEC 5.11)
const escapeHtml = (value) => String(value ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
function render(template, values) {
  const missing = new Set();
  const text = String(template ?? '').replace(/\{\{\s*(\w+)\s*\}\}/g, (token, key) => {
    if (values[key] === undefined || values[key] === null || String(values[key]).trim() === '') { missing.add(key); return token; }
    return String(values[key]);
  });
  return { text, missing: [...missing] };
}
const now = $now.setZone(TZ);
const SEQUENCE_ID = 'WAITLIST_NURTURE';

const leads = rowsOf('Lane 4 · Read LEADS');
const steps = rowsOf('Lane 4 · Read SEQUENCES')
  .filter((row) => String(row.sequence_id).trim() === SEQUENCE_ID && isTrue(row.active))
  .map((row) => ({ ...row, step: Number(row.step) }))
  .filter((row) => Number.isInteger(row.step) && row.step > 0)
  .sort((a, b) => a.step - b.step);
const stepByNumber = new Map(steps.map((row) => [row.step, row]));

// ---- BRIEF values used as placeholders. BRIEF text may itself contain {{launch_date}} style tokens, so fill those first.
const realLaunch = parseDate(S.LAUNCH_DATE);
const dateText = (d) => (d ? d.setLocale('en').toFormat('cccc, d LLLL') : '');
const base = {
  launch_date: dateText(realLaunch),
  public_launch_date: dateText(realLaunch?.plus({ days: Number(S.EARLY_ACCESS_DAYS) })),
  waitlist_form_url: S.WAITLIST_FORM_URL,
  sender_name: S.SENDER_NAME,
  unsubscribe_line: S.UNSUBSCRIBE_LINE,
};
const brief = {};
for (const row of rowsOf('Lane 4 · Read BRIEF')) {
  const key = String(row.key ?? '').trim();
  if (key) brief[key] = String(row.value ?? '').trim();
}
// The discount code is only revealed by Lane 5 on launch day, so it is never a Lane 4 placeholder.
const briefValues = {};
for (const key of ['brand_name', 'brand_instagram', 'collection_name', 'founder_name', 'offer_percent']) {
  if (brief[key] !== undefined) briefValues[key] = render(brief[key], base).text;
}
const common = { ...base, ...briefValues };

const out = [];
const problem = (lead, message, extra = {}) => out.push({ json: { action: 'skip', needs_email: false, lead_id: String(lead?.lead_id ?? '').trim(), row_number: lead?.row_number ?? '', pick_error: message, ...extra } });

if (!steps.length) {
  // No active steps at all means SEQUENCES is misconfigured, so do NOT mark anyone as finished.
  const anyDue = leads.some((lead) => ['new', 'nurturing'].includes(String(lead.status).trim()) && isTrue(lead.consent));
  if (anyDue) problem(null, `no active ${SEQUENCE_ID} steps in SEQUENCES`, { entity_type: 'sequence', entity_id: SEQUENCE_ID });
  return out;
}

const candidates = [];
for (const lead of leads) {
  const status = String(lead.status ?? '').trim();
  if (!['new', 'nurturing'].includes(status)) continue;
  if (!isTrue(lead.consent)) continue;
  if (String(lead.email_allowed ?? '').trim().toUpperCase() === 'FALSE') continue;
  const nextRaw = String(lead.next_action_at ?? '').trim();
  const lastRaw = String(lead.last_contacted_at ?? '').trim();
  const bad = [];
  if (nextRaw && !parseTs(nextRaw)) bad.push('next_action_at');
  if (lastRaw && !parseTs(lastRaw)) bad.push('last_contacted_at');
  if (bad.length) { problem(lead, `invalid value in ${bad.join(', ')}`); continue; }
  const next = parseTs(nextRaw);
  if (next && next.toMillis() > now.toMillis()) continue;      // not due yet
  if (!gapOk(lead, now)) continue;                              // too soon after the last email of any lane
  candidates.push({ lead, sortKey: next ? next.toMillis() : 0 });
}
candidates.sort((a, b) => a.sortKey - b.sortKey);

let sends = 0;
const maxSends = Math.max(0, Number(S.MAX_SENDS_PER_RUN) || 0);
for (const { lead } of candidates) {
  const leadId = String(lead.lead_id ?? '').trim();
  const email = String(lead.email ?? '').trim().toLowerCase();
  const missingFields = [];
  if (!leadId) missingFields.push('lead_id');
  if (!email) missingFields.push('email');
  const seqStepRaw = String(lead.seq_step ?? '').trim();
  const seqStep = seqStepRaw === '' ? 0 : Number(seqStepRaw);
  if (!Number.isInteger(seqStep) || seqStep < 0) missingFields.push('seq_step');
  if (missingFields.length) { problem(lead, `missing or invalid ${missingFields.join(', ')}`); continue; }

  const step = seqStep + 1;
  const stepRow = stepByNumber.get(step);
  const status = String(lead.status).trim();
  if (!stepRow) {
    out.push({ json: { action: 'complete', needs_email: false, lead_id: leadId, status_from: status, sequence_id: SEQUENCE_ID, step: seqStep } });
    continue;
  }
  if (sends >= maxSends) break;

  const text = render(stepRow.subject_template, { ...common, first_name: lead.first_name, city: lead.city });
  const html = render(stepRow.body_template, {
    ...common, first_name: escapeHtml(lead.first_name), city: escapeHtml(lead.city),
  });
  const missingTokens = [...new Set([...text.missing, ...html.missing])];
  if (missingTokens.length) { problem(lead, `template ${stepRow.step_key} has empty or unknown placeholder(s): ${missingTokens.join(', ')}`); continue; }

  const nextStep = stepByNumber.get(step + 1);
  const isLast = !nextStep;
  out.push({
    json: {
      action: 'send', needs_email: true, lead_id: leadId, to_email: email, subject: text.text.replace(/\s+/g, ' ').trim(), html: html.text,
      sender_name: S.SENDER_NAME, sequence_id: SEQUENCE_ID, step, step_key: stepRow.step_key, is_last: isLast,
      next_delay_days: isLast ? null : Number(nextStep.delay_days),
      status_from: status, thread_ids_before: String(lead.thread_ids ?? ''),
    },
  });
  sends++;
}
return out;

// Re-checks the lead against a FRESH read of LEADS, right before the safety gate (session 5 cross-lane guard).
// "Pick due leads" read the sheet at the start of the run, up to ~45 s ago. Meanwhile Lane 7 may have marked the lead
// hot / replied / unsubscribed, or Lane 2 / 5 may have just emailed it. Sending now would ignore that, and our row update
// would overwrite Lane 7's status. So: still new/nurturing, same seq_step, consent, not blocked, gap respected? Else skip quietly.
const S = $('Lane 4 · Settings to object').first().json;
// ---- time helpers (SPEC 5.2 / 5.3)
const TZ = 'Asia/Kolkata';
const STAMP = "yyyy-MM-dd'T'HH:mm:ssZZ";
const nowTs = () => $now.setZone(TZ).toFormat(STAMP);
function parseTs(value) {
  if (value === undefined || value === null || String(value).trim() === '') return null;
  const text = String(value).trim();
  const tries = [
    () => DateTime.fromISO(text, { zone: TZ }),
    () => DateTime.fromFormat(text, 'yyyy-MM-dd HH:mm:ss', { zone: TZ }),
    () => DateTime.fromFormat(text, 'yyyy-MM-dd HH:mm', { zone: TZ }),
    () => DateTime.fromFormat(text, 'dd/MM/yyyy HH:mm:ss', { zone: TZ }),
    () => DateTime.fromFormat(text, 'dd/MM/yyyy', { zone: TZ }),
  ];
  for (const attempt of tries) { const d = attempt(); if (d.isValid) return d.setZone(TZ); }
  return null;
}
const parseDate = (value) => parseTs(value)?.startOf('day') ?? null;
const addDays = (dateTime, days) => dateTime.plus({ milliseconds: Number(days) * S.DAY_MS });
function launchAt(S) {
  if (S.IS_DEMO) return parseTs(S.DEMO_LAUNCH_AT);
  const [hour, minute] = String(S.LAUNCH_TIME).split(':').map(Number);
  return parseDate(S.LAUNCH_DATE)?.set({ hour, minute }) ?? null;
}
const gapOk = (row, now) => !parseTs(row.last_contacted_at) || now.toMillis() - parseTs(row.last_contacted_at).toMillis() >= Number(S.MIN_EMAIL_GAP_DAYS) * S.DAY_MS;
const isTrue = (value) => String(value ?? '').trim().toUpperCase() === 'TRUE';
// Rows read from a sheet; an empty tab comes back as one empty item (and blank rows only have a row_number), so drop those.
const rowsOf = (nodeName) => $(nodeName).all().map((item) => item.json).filter((row) => row && Object.entries(row).some(([key, v]) => key !== 'row_number' && String(v ?? '').trim() !== ''));
const now = $now.setZone(TZ);
const job = $('Lane 4 · Needs email?').first().json;                 // this round's lead (latest run of the IF)
const fresh = $input.all().map((item) => item.json).find((row) => String(row?.lead_id ?? '').trim() === job.lead_id);
const reasons = [];
if (!fresh) reasons.push('lead row not found');
else {
  const status = String(fresh.status ?? '').trim();
  const seqStepRaw = String(fresh.seq_step ?? '').trim();
  if (!['new', 'nurturing'].includes(status)) reasons.push(`status is now ${status}`);
  if ((seqStepRaw === '' ? 0 : Number(seqStepRaw)) !== job.step - 1) reasons.push(`seq_step is now ${seqStepRaw}`);
  if (!isTrue(fresh.consent) || String(fresh.email_allowed ?? '').trim().toUpperCase() === 'FALSE') reasons.push('no longer allowed');
  if (!gapOk(fresh, now)) reasons.push('another lane emailed this lead moments ago');
}
return [{ json: { ...job, still_due: reasons.length === 0, stale_reason: reasons.join('; '), thread_ids_before: String(fresh?.thread_ids ?? job.thread_ids_before ?? '') }, pairedItem: { item: 0 } }];

// Lane 4 · Demo safety gate: input items carry the recipient in `to_email`.
const S = $('Lane 4 · Settings to object').first().json;
const PUBLIC = ['gmail.com', 'googlemail.com', 'yahoo.com', 'yahoo.in', 'outlook.com', 'hotmail.com', 'live.com', 'icloud.com', 'rediffmail.com', 'proton.me', 'protonmail.com'];
const list = (value) => String(value ?? '').toLowerCase().split(',').map((part) => part.trim()).filter(Boolean);
function checkRecipient(email) {
  const match = /^([a-z0-9._%-]+)(\+[a-z0-9._%-]*)?@([a-z0-9.-]+\.[a-z]{2,})$/.exec(email);
  if (!match) return { ok: false, reason: 'not a single valid email address' };
  const base = `${match[1]}@${match[3]}`;                      // plus-tag removed
  const inboxes = [...list(S.ALLOWED_DEMO_INBOXES), ...list(S.SENDER_EMAIL)];
  const domains = list(S.ALLOWED_EMAIL_DOMAINS).map((d) => d.replace(/^@/, '')).filter((d) => !PUBLIC.includes(d));
  if (inboxes.includes(base)) return { ok: true, reason: 'demo inbox' };
  if (domains.includes(match[3])) return { ok: true, reason: 'demo domain' };
  return { ok: false, reason: 'not in ALLOWED_DEMO_INBOXES or ALLOWED_EMAIL_DOMAINS' };
}
return $input.all().map((item) => {
  const to = String(item.json.to_email ?? '').trim().toLowerCase();
  const check = checkRecipient(to);
  return { json: { ...item.json, safe_to: check.ok ? to : '', gate_ok: check.ok, gate_reason: check.reason } };
});

// Runs once per lead, after the email step has finished one way or another (sent, send failed, blocked,
// or nothing to send). Decides what to write back to LEADS and which events to log.
// Only this node knows the outcome, so every branch of the loop meets here.
const S = $('Lane 4 · Settings to object').first().json;
// ---- time helpers (SPEC 5.2 / 5.3)
const TZ = 'Asia/Kolkata';
const STAMP = "yyyy-MM-dd'T'HH:mm:ssZZ";
const nowTs = () => $now.setZone(TZ).toFormat(STAMP);
function parseTs(value) {
  if (value === undefined || value === null || String(value).trim() === '') return null;
  const text = String(value).trim();
  const tries = [
    () => DateTime.fromISO(text, { zone: TZ }),
    () => DateTime.fromFormat(text, 'yyyy-MM-dd HH:mm:ss', { zone: TZ }),
    () => DateTime.fromFormat(text, 'yyyy-MM-dd HH:mm', { zone: TZ }),
    () => DateTime.fromFormat(text, 'dd/MM/yyyy HH:mm:ss', { zone: TZ }),
    () => DateTime.fromFormat(text, 'dd/MM/yyyy', { zone: TZ }),
  ];
  for (const attempt of tries) { const d = attempt(); if (d.isValid) return d.setZone(TZ); }
  return null;
}
const parseDate = (value) => parseTs(value)?.startOf('day') ?? null;
const addDays = (dateTime, days) => dateTime.plus({ milliseconds: Number(days) * S.DAY_MS });
function launchAt(S) {
  if (S.IS_DEMO) return parseTs(S.DEMO_LAUNCH_AT);
  const [hour, minute] = String(S.LAUNCH_TIME).split(':').map(Number);
  return parseDate(S.LAUNCH_DATE)?.set({ hour, minute }) ?? null;
}
const gapOk = (row, now) => !parseTs(row.last_contacted_at) || now.toMillis() - parseTs(row.last_contacted_at).toMillis() >= Number(S.MIN_EMAIL_GAP_DAYS) * S.DAY_MS;
const isTrue = (value) => String(value ?? '').trim().toUpperCase() === 'TRUE';
// Rows read from a sheet; an empty tab comes back as one empty item (and blank rows only have a row_number), so drop those.
const rowsOf = (nodeName) => $(nodeName).all().map((item) => item.json).filter((row) => row && Object.entries(row).some(([key, v]) => key !== 'row_number' && String(v ?? '').trim() !== ''));
const now = $now.setZone(TZ);
const input = $json;

let ctx;
let outcome;
if (input.gate_ok === false) { ctx = input; outcome = 'blocked'; }
else if (input.action === 'complete' || input.action === 'skip') { ctx = input; outcome = input.action; }
else {
  // Gmail's own output has no lead data, so fetch the item that went into Gmail (matched by n8n's item pairing).
  ctx = $('Lane 4 · Recipient allowed?').item.json;
  outcome = (input.error || !input.id) ? 'failed' : 'sent';
}

const stamp = (d) => d.toFormat(STAMP);
const leadId = ctx.lead_id;
const update = { lead_id: leadId, updated_at: stamp(now) };
const events = [];
let hasUpdate = true;

if (outcome === 'sent') {
  const threads = String(ctx.thread_ids_before || '').split(',').map((t) => t.trim()).filter(Boolean);
  if (input.threadId) threads.push(String(input.threadId));
  const statusTo = ctx.is_last ? 'nurture_done' : 'nurturing';
  Object.assign(update, {
    seq_step: ctx.step, status: statusTo, last_contacted_at: stamp(now),
    next_action_at: ctx.is_last ? '' : stamp(addDays(now, ctx.next_delay_days)),
    thread_ids: threads.slice(-10).join(','),
  });
  events.push({ event_type: 'email_sent', entity_type: 'lead', entity_id: leadId, status_from: ctx.status_from, status_to: statusTo, channel: 'email',
    detail: `${ctx.sequence_id} step ${ctx.step} sent`, meta: { sequence_id: ctx.sequence_id, step: ctx.step, thread_id: String(input.threadId ?? '') } });
  if (ctx.is_last) events.push({ event_type: 'sequence_completed', entity_type: 'lead', entity_id: leadId, status_from: ctx.status_from, status_to: statusTo, channel: 'email',
    detail: `${ctx.sequence_id} finished after step ${ctx.step}`, meta: { sequence_id: ctx.sequence_id } });
} else if (outcome === 'failed') {
  // Do not advance seq_step; try again a little later (0.1 day on the demo clock).
  update.next_action_at = stamp(addDays(now, 0.1));
  const message = typeof input.error === 'string' ? input.error : (input.error?.message || JSON.stringify(input.error ?? 'Gmail returned no message id'));
  events.push({ event_type: 'email_failed', entity_type: 'lead', entity_id: leadId, channel: 'email',
    detail: `${ctx.sequence_id} step ${ctx.step} not sent: ${message}`, meta: { sequence_id: ctx.sequence_id, step: ctx.step, error: String(message).slice(0, 300) } });
} else if (outcome === 'blocked') {
  Object.assign(update, { status: 'blocked', email_allowed: 'FALSE', next_action_at: '' });
  events.push({ event_type: 'email_blocked', entity_type: 'lead', entity_id: leadId, status_from: ctx.status_from, status_to: 'blocked', channel: 'email',
    detail: `${ctx.to_email} blocked by the safety gate: ${ctx.gate_reason}`, meta: { reason: ctx.gate_reason } });
} else if (outcome === 'complete') {
  Object.assign(update, { status: 'nurture_done', next_action_at: '' });
  events.push({ event_type: 'sequence_completed', entity_type: 'lead', entity_id: leadId, status_from: ctx.status_from, status_to: 'nurture_done', channel: 'email',
    detail: `${ctx.sequence_id} has no step ${ctx.step + 1}; sequence finished`, meta: { sequence_id: ctx.sequence_id } });
} else {
  // skip: bad row or bad template. Leave the row alone and say why.
  hasUpdate = false;
  events.push({ event_type: 'error', entity_type: ctx.entity_type || 'lead', entity_id: ctx.entity_id ?? ctx.lead_id ?? (ctx.row_number ? `row ${ctx.row_number}` : ''), channel: 'sheet',
    detail: ctx.pick_error, meta: { node: 'Lane 4 · Pick due leads', message: ctx.pick_error } });
}

return { json: { outcome, lead_id: leadId, has_update: hasUpdate, row_update: update, events } };

// The Google Sheets update node writes every field it receives, so pass on ONLY the key column
// and the columns this lane owns (SPEC 5.4).
return { json: $json.row_update };

// Turns the outcome(s) of this loop round into EVENTS_LOG rows (SPEC 5.6).
const S = $('Lane 4 · Settings to object').first().json;
const TZ = 'Asia/Kolkata';
// ---- event builder (SPEC 5.6)
const now = $now.setZone(TZ);
const used = new Set();
function eventId() {
  let id;
  do { id = `EV-${now.toFormat('yyyyMMddHHmmssSSS')}-${Math.random().toString(36).slice(2, 6).toUpperCase().padEnd(4, '0')}`; } while (used.has(id));
  used.add(id);
  return id;
}
function event({ event_type, entity_type, entity_id = '', status_from = '', status_to = '', channel = '', detail = '', meta = {} }) {
  return {
    event_id: eventId(), ts: now.toFormat("yyyy-MM-dd'T'HH:mm:ssZZ"), lane: 4,
    event_type, entity_type, entity_id, status_from, status_to, channel,
    detail: String(detail).slice(0, 200), meta_json: JSON.stringify(meta),
    execution_id: String($execution.id), demo_mode: S.IS_DEMO ? 'TRUE' : 'FALSE',
  };
}
const rows = [];
$input.all().forEach((item, index) => {
  const decided = $('Lane 4 · Decide outcome').itemMatching(index).json;
  for (const e of decided.events) rows.push({ json: event(e) });
});
return rows;

// Pause between two emails (SEND_DELAY_SECONDS). Only after an attempt to send; nothing else needs a pause.
const S = $('Lane 4 · Settings to object').first().json;
const attempted = $input.all().some((item) => ['email_sent', 'email_failed'].includes(item.json.event_type));
return [{ json: { pause_seconds: attempted ? Math.min(60, Math.max(0, Number(S.SEND_DELAY_SECONDS) || 0)) : 0 } }];
